<?php
namespace App\Console\Commands;
use App\Services\StorageCleanupService; use App\Services\StorageMetricsService; use Illuminate\Console\Command;
class CleanupStorageCommand extends Command {protected $signature='simpleview:cleanup-storage {--dry-run} {--temp} {--logs} {--expired-backups} {--orphan-thumbnails} {--force}';protected $description='Simula o ejecuta limpiezas seguras de almacenamiento';public function handle(StorageCleanupService $s,StorageMetricsService $m):int{$selected=['temp'=>$this->option('temp'),'logs'=>$this->option('logs'),'expired_backups'=>$this->option('expired-backups'),'orphan_thumbnails'=>$this->option('orphan-thumbnails')];if(!array_filter($selected))$selected=['temp'=>true,'logs'=>true,'expired_backups'=>true,'orphan_thumbnails'=>true];$execute=(bool)$this->option('force')&&!$this->option('dry-run');$r=$s->cleanup($selected,$execute);$this->info(($execute?'Limpieza ejecutada':'Simulación').': '.count($r['files']).' archivos, '.number_format($r['bytes']/1048576,1).' MB.');if($execute)$m->measure();return self::SUCCESS;}}
